#!/usr/bin/env python3
"""Quantum word projection onto theory DAG and Bost-Connes KMS filtering."""

import numpy as np
import sympy as sp

# 1. POS-tagged Word2Vec Poset definition
# We define a causal preorder where word_A <= word_B if B semantically entails
# or follows A in a physical/geometric context.
WORD_POSET = {
    "quantum": ["spin", "geometry", "spacetime"],
    "spin": ["geometry", "spacetime"],
    "geometry": ["spacetime"],
    "spacetime": []
}

# The Theory DAG nodes (nodes in InfoGeometry.Canonical)
DAG_NODES = {
    "AutoGeneratedKrein": 0,
    "SpinConnection": 1,
    "PauliParavector": 2,
    "CausalFunctor": 3,
    "ModularEvolution": 4
}

# Poset Homomorphism Map: Word2Vec -> DAG
POSET_MAP = {
    "quantum": "AutoGeneratedKrein",
    "spin": "SpinConnection",
    "geometry": "PauliParavector",
    "spacetime": "CausalFunctor"
}

# 2. Local Clifford/Pin basis (Pauli matrices for doubled space representation)
SIGMA_X = np.array([[0, 1], [1, 0]], dtype=complex)
SIGMA_Y = np.array([[0, -1j], [1j, 0]], dtype=complex)
SIGMA_Z = np.array([[1, 0], [0, -1]], dtype=complex)
EYE = np.eye(2, dtype=complex)

def get_clifford_basis(node):
    """Returns a local Pin/Spin basis associated with a DAG node."""
    if node == "AutoGeneratedKrein":
        return [SIGMA_X, SIGMA_Y]
    elif node in ("SpinConnection", "PauliParavector"):
        return [SIGMA_X, SIGMA_Y, SIGMA_Z]
    else:
        return [EYE]

# 3. Attention Head quantum projection
def attention_projection(word_vector, transition_matrix):
    """Projects a word vector onto the eigenspaces of the attention matrix."""
    eigenvalues, eigenvectors = np.linalg.eig(transition_matrix)
    # Project vector onto each eigenvector
    projections = []
    for i in range(len(eigenvalues)):
        v = eigenvectors[:, i]
        proj_coeff = np.dot(np.conj(v), word_vector)
        projections.append((eigenvalues[i], proj_coeff * v))
    return projections

# 4. Bost-Connes Prime Mapping for Fractal Boundary Encoding
# Every word is mapped to a unique prime number.
PRIME_MAP = {
    "quantum": 2,
    "spin": 3,
    "geometry": 5,
    "spacetime": 7
}
INV_PRIME_MAP = {v: k for k, v in PRIME_MAP.items()}

def encode_chain(words):
    """Encodes a chain of words as a state index on the Bost-Connes boundary."""
    n = 1
    for w in words:
        if w in PRIME_MAP:
            n *= PRIME_MAP[w]
    return n

def kms_state_filter(state_n, beta, threshold=0.01):
    """Filters the state via a KMS expectation at inverse temperature beta."""
    # The energy of the state |n> is ln(n)
    # The partition function value is n^(-beta)
    # We find the prime factors of state_n
    factors = []
    temp_n = state_n
    for p in sorted(INV_PRIME_MAP.keys()):
        count = 0
        while temp_n % p == 0:
            count += 1
            temp_n //= p
        if count > 0:
            # Probability under KMS state is p^(-beta)
            prob = p ** (-beta)
            if prob >= threshold:
                factors.append((INV_PRIME_MAP[p], count, prob))
    return factors

def main():
    print("=== Quantum Poset & Fractal Boundary Projection Pipeline ===")
    
    # Verify poset map preserves order
    print("\n1. Poset Homomorphism Mapping Verification:")
    for w1, relations in WORD_POSET.items():
        for w2 in relations:
            n1 = POSET_MAP[w1]
            n2 = POSET_MAP[w2]
            idx1 = DAG_NODES[n1]
            idx2 = DAG_NODES[n2]
            # Verify order is preserved: if w1 <= w2 then DAG(n1) <= DAG(n2)
            preserves = idx1 <= idx2
            print(f"   {w1} <= {w2}  ->  {n1}({idx1}) <= {n2}({idx2}) : {preserves}")

    # Generate basis for mapped nodes
    print("\n2. Staging Pin/Spin Basis at Projected DAG Nodes:")
    for w, node in POSET_MAP.items():
        basis = get_clifford_basis(node)
        print(f"   Word '{w}' -> Node '{node}' has basis of size {len(basis)}")

    # Attention Head quantum projection
    print("\n3. Attention Head Quantum Projection:")
    # Simple 2D attention transition matrix
    A = np.array([[0.8, 0.6], [0.6, -0.8]])
    word_embedding = np.array([1.0, 0.0])  # "quantum" embedding vector
    proj = attention_projection(word_embedding, A)
    for i, (val, vec) in enumerate(proj):
        print(f"   Eigenvalue {val:.4f}: projection vector {vec}")

    # Bost-Connes Fractal Boundary Encoding & KMS Filtering
    print("\n4. Bost-Connes KMS Fractal Filtering:")
    word_chain = ["quantum", "spin", "geometry"]
    encoded_state = encode_chain(word_chain)
    print(f"   Input word chain: {word_chain}")
    print(f"   Encoded state index (N): {encoded_state}")

    # High temperature (beta = 0.5) - allows more noise/words
    print("\n   [High Temp: beta = 0.5]")
    filtered_high = kms_state_filter(encoded_state, beta=0.5)
    for word, count, prob in filtered_high:
        print(f"   - Keep '{word}' (count {count}, KMS prob {prob:.4f})")

    # Low temperature (beta = 3.0) - restricts to low-energy/low-prime states
    print("\n   [Low Temp: beta = 3.0]")
    filtered_low = kms_state_filter(encoded_state, beta=3.0)
    for word, count, prob in filtered_low:
        print(f"   - Keep '{word}' (count {count}, KMS prob {prob:.4f})")

if __name__ == "__main__":
    main()
